blocks.body:
{
    "level": "A1–A2",
    "intro": "У цій темі ти вивчиш <strong>базовий порядок слів<\/strong> в англійських ствердних реченнях: структуру S–V–O, розташування прислівників частотності та обставин часу й місця.",
    "rules": [
        {
            "label": "Базова структура",
            "color": "emerald",
            "text": "<strong>Subject + Verb + Object<\/strong> — основа англійського речення:",
            "example": "She reads books."
        },
        {
            "label": "Прислівники частотності",
            "color": "blue",
            "text": "<strong>Always, often, sometimes, never<\/strong> стоять перед основним дієсловом:",
            "example": "I always drink tea in the morning."
        },
        {
            "label": "Час і місце",
            "color": "amber",
            "text": "<strong>Place + Time<\/strong> зазвичай в кінці речення:",
            "example": "We play football in the park every Sunday."
        }
    ]
}

{
    "title": "1. Структура S–V–O (Subject–Verb–Object)",
    "intro": "Англійське ствердне речення будується за схемою:",
    "items": [
        {
            "label": "S — Subject",
            "title": "Підмет",
            "subtitle": "Хто або що виконує дію (I, you, she, Tom, the dog)"
        },
        {
            "label": "V — Verb",
            "title": "Дієслово",
            "subtitle": "Дія або стан (read, eat, is, have)"
        },
        {
            "label": "O — Object",
            "title": "Додаток",
            "subtitle": "На кого\/що спрямована дія (book, coffee, him)"
        }
    ]
}

{
    "title": "2. Прислівники частотності (Adverbs of Frequency)",
    "sections": [
        {
            "label": "Перед основним дієсловом",
            "color": "emerald",
            "description": "Прислівники <strong>always, usually, often, sometimes, rarely, never<\/strong> ставляться <strong>перед<\/strong> основним дієсловом.",
            "examples": [
                {
                    "en": "She always eats breakfast.",
                    "ua": "Вона завжди снідає."
                },
                {
                    "en": "I often go to the gym.",
                    "ua": "Я часто ходжу до спортзалу."
                },
                {
                    "en": "They never drink coffee.",
                    "ua": "Вони ніколи не пʼють каву."
                }
            ]
        },
        {
            "label": "Після дієслова TO BE",
            "color": "sky",
            "description": "Якщо в реченні дієслово <strong>to be<\/strong> (am, is, are, was, were), прислівник частотності ставиться <strong>після<\/strong> нього.",
            "examples": [
                {
                    "en": "He is always late.",
                    "ua": "Він завжди запізнюється."
                },
                {
                    "en": "She is usually happy.",
                    "ua": "Вона зазвичай щаслива."
                },
                {
                    "en": "They are never bored.",
                    "ua": "Їм ніколи не нудно."
                }
            ]
        },
        {
            "label": "Sometimes \/ Usually на початку",
            "color": "amber",
            "description": "Деякі прислівники (<strong>sometimes, usually, often<\/strong>) можуть стояти на початку речення для акценту.",
            "examples": [
                {
                    "en": "Sometimes I read before bed.",
                    "ua": "Іноді я читаю перед сном."
                },
                {
                    "en": "Usually we have dinner at 7.",
                    "ua": "Зазвичай ми вечеряємо о 7-й."
                }
            ],
            "note": "<strong>Always<\/strong> та <strong>never<\/strong> рідко ставлять на початку речення."
        }
    ]
}

{
    "title": "3. Обставини часу (Time Adverbials)",
    "sections": [
        {
            "label": "В кінці речення",
            "color": "emerald",
            "description": "Обставини часу (<strong>yesterday, every day, at 7 o'clock, last week<\/strong>) зазвичай стоять <strong>в кінці<\/strong> речення.",
            "examples": [
                {
                    "en": "I wake up at 6 o'clock.",
                    "ua": "Я прокидаюся о шостій годині."
                },
                {
                    "en": "She studies English every day.",
                    "ua": "Вона вчить англійську щодня."
                },
                {
                    "en": "We went to the cinema last night.",
                    "ua": "Ми ходили в кіно вчора ввечері."
                }
            ]
        },
        {
            "label": "На початку речення",
            "color": "sky",
            "description": "Для акценту обставини часу можна поставити <strong>на початку<\/strong>.",
            "examples": [
                {
                    "en": "Yesterday, I met an old friend.",
                    "ua": "Вчора я зустрів старого друга."
                },
                {
                    "en": "Every morning, she jogs in the park.",
                    "ua": "Щоранку вона бігає в парку."
                }
            ]
        }
    ]
}

{
    "title": "4. Обставини місця (Place Adverbials)",
    "sections": [
        {
            "label": "Після дієслова \/ додатка",
            "color": "emerald",
            "description": "Обставини місця (<strong>at school, in the park, at home<\/strong>) ставляться <strong>після дієслова<\/strong> або <strong>додатка<\/strong>.",
            "examples": [
                {
                    "en": "He works at the office.",
                    "ua": "Він працює в офісі."
                },
                {
                    "en": "She reads books in her room.",
                    "ua": "Вона читає книжки у своїй кімнаті."
                }
            ]
        },
        {
            "label": "Place перед Time",
            "color": "sky",
            "description": "Якщо є і місце, і час, порядок такий: <strong>Place + Time<\/strong>.",
            "examples": [
                {
                    "en": "We eat dinner at home on Sundays.",
                    "ua": "Ми вечеряємо вдома по неділях."
                },
                {
                    "en": "The children play in the park every afternoon.",
                    "ua": "Діти граються в парку щодня після обіду."
                }
            ]
        }
    ]
}

{
    "title": "5. Повна структура речення",
    "intro": "Повний порядок елементів у ствердному реченні:",
    "rows": [
        {
            "en": "Subject",
            "ua": "Підмет",
            "note": "She, Tom, They"
        },
        {
            "en": "Adverb of Frequency",
            "ua": "Прислівник частотності",
            "note": "always, often, never (перед основним дієсловом)"
        },
        {
            "en": "Verb",
            "ua": "Дієслово",
            "note": "reads, eats, plays"
        },
        {
            "en": "Object",
            "ua": "Додаток",
            "note": "books, coffee, football"
        },
        {
            "en": "Place",
            "ua": "Місце",
            "note": "at school, in the park"
        },
        {
            "en": "Time",
            "ua": "Час",
            "note": "every day, yesterday, at 7 o'clock"
        }
    ],
    "warning": "📌 Формула: <strong>S + (Adv) + V + O + Place + Time<\/strong>"
}

{
    "title": "6. Типові помилки україномовних",
    "items": [
        {
            "label": "Помилка 1",
            "color": "rose",
            "title": "Зміна порядку S–V–O під впливом української.",
            "wrong": "Reads she books every day.",
            "right": "✅ <span class=\"font-mono\">She reads books every day.<\/span>"
        },
        {
            "label": "Помилка 2",
            "color": "amber",
            "title": "Неправильне розташування прислівника частотності.",
            "wrong": "She reads always books.",
            "right": "✅ <span class=\"font-mono\">She always reads books.<\/span>"
        },
        {
            "label": "Помилка 3",
            "color": "sky",
            "title": "Час посередині речення замість кінця.",
            "wrong": "I go every day to school.",
            "right": "✅ <span class=\"font-mono\">I go to school every day.<\/span>"
        }
    ]
}

{
    "title": "7. Короткий конспект",
    "items": [
        "Базова структура: <strong>S + V + O<\/strong> (підмет + дієслово + додаток).",
        "Прислівники частотності (<em>always, often, never<\/em>) — <strong>перед основним дієсловом<\/strong> або <strong>після to be<\/strong>.",
        "Обставини часу (<em>yesterday, every day<\/em>) — зазвичай <strong>в кінці<\/strong> речення.",
        "Обставини місця (<em>at home, in the park<\/em>) — після додатка, <strong>перед часом<\/strong>.",
        "Формула: <strong>S + (Adv) + V + O + Place + Time<\/strong>."
    ]
}

{
    "title": "8. Практика",
    "select_title": "Вправа 1. Обери правильний варіант",
    "select_intro": "Обери речення з правильним порядком слів.",
    "selects": [
        {
            "label": "a) She always drinks coffee. / b) Always she drinks coffee.",
            "prompt": "Який варіант правильний?",
            "answer": "a"
        },
        {
            "label": "a) I go to work every day. / b) I every day go to work.",
            "prompt": "Який варіант правильний?",
            "answer": "a"
        },
        {
            "label": "a) He in the office works. / b) He works in the office.",
            "prompt": "Який варіант правильний?",
            "answer": "b"
        }
    ],
    "options": [
        "a",
        "b"
    ],
    "input_title": "Вправа 2. Розташуй слова у правильному порядку",
    "input_intro": "Склади речення з поданих слів.",
    "inputs": [
        {
            "before": "(she / reads / books / often)",
            "after": "→",
            "answer": "She often reads books."
        },
        {
            "before": "(every morning / I / breakfast / eat)",
            "after": "→",
            "answer": "I eat breakfast every morning."
        },
        {
            "before": "(at home / on Sundays / we / dinner / have)",
            "after": "→",
            "answer": "We have dinner at home on Sundays."
        }
    ],
    "rephrase_title": "Вправа 3. Виправ помилки",
    "rephrase_intro": "Знайди і виправ помилку у порядку слів.",
    "rephrase": [
        {
            "example_label": "Приклад:",
            "example_original": "Plays he football every day.",
            "example_target": "He plays football every day."
        },
        {
            "original": "1. She reads always books in the evening.",
            "placeholder": "Виправ порядок слів",
            "answer": "She always reads books in the evening."
        },
        {
            "original": "2. We go every week to the supermarket.",
            "placeholder": "Виправ порядок слів",
            "answer": "We go to the supermarket every week."
        }
    ]
}

{
    "title": "Сторінки підрозділу Word Order",
    "items": [
        {
            "label": "Basic Word Order — Базовий порядок слів",
            "current": true
        },
        {
            "label": "Word Order in Questions and Negatives — Порядок слів у питаннях і запереченнях",
            "current": false
        },
        {
            "label": "Word Order with Adverbs and Adverbials — Прислівники й обставини",
            "current": false
        },
        {
            "label": "Word Order with Verbs and Objects — Дієслова й додатки",
            "current": false
        },
        {
            "label": "Advanced Word Order / Emphasis — Інверсія й акцент",
            "current": false
        }
    ]
}

{
    "level": "A1–A2",
    "intro": "У цій темі ти вивчиш <strong>порядок слів у питаннях і запереченнях<\/strong>: використання допоміжних дієслів, структуру Wh-питань та типові помилки.",
    "rules": [
        {
            "label": "Yes\/No питання",
            "color": "emerald",
            "text": "<strong>Do\/Does\/Did + Subject + Verb<\/strong> — базова структура питання:",
            "example": "Do you like pizza?"
        },
        {
            "label": "Wh-питання",
            "color": "blue",
            "text": "<strong>Wh-word + Auxiliary + Subject + Verb<\/strong> — питання з where, what, why:",
            "example": "Where do you live?"
        },
        {
            "label": "Заперечення",
            "color": "amber",
            "text": "<strong>Subject + Auxiliary + not + Verb<\/strong> — структура заперечення:",
            "example": "I don't like apples."
        }
    ]
}

{
    "title": "1. Допоміжні дієслова (Auxiliary Verbs)",
    "intro": "Для побудови питань і заперечень потрібні допоміжні дієслова:",
    "items": [
        {
            "label": "Do",
            "title": "I \/ You \/ We \/ They",
            "subtitle": "Do you like coffee? I do not know."
        },
        {
            "label": "Does",
            "title": "He \/ She \/ It",
            "subtitle": "Does she work? He does not play."
        },
        {
            "label": "Did",
            "title": "Минулий час",
            "subtitle": "Did they come? We did not see."
        }
    ]
}

{
    "title": "2. Yes\/No питання",
    "sections": [
        {
            "label": "Звичайні дієслова",
            "color": "emerald",
            "description": "Для звичайних дієслів використовуй <strong>do\/does\/did<\/strong> перед підметом.",
            "examples": [
                {
                    "en": "Do you like pizza?",
                    "ua": "Ти любиш піцу?"
                },
                {
                    "en": "Does she play tennis?",
                    "ua": "Вона грає в теніс?"
                },
                {
                    "en": "Did they watch the show?",
                    "ua": "Вони дивились шоу?"
                }
            ]
        },
        {
            "label": "To be та модальні дієслова",
            "color": "sky",
            "description": "Для <strong>to be<\/strong> та модальних дієслів просто міняй місцями підмет і дієслово — do\/does\/did не потрібні.",
            "examples": [
                {
                    "en": "Are you ready?",
                    "ua": "Ти готовий?"
                },
                {
                    "en": "Is he coming?",
                    "ua": "Він іде?"
                },
                {
                    "en": "Can you swim?",
                    "ua": "Ти вмієш плавати?"
                },
                {
                    "en": "Have you finished?",
                    "ua": "Ти закінчив?"
                }
            ]
        }
    ]
}

{
    "title": "3. Wh-питання (Wh-Questions)",
    "sections": [
        {
            "label": "Структура Wh-питань",
            "color": "emerald",
            "description": "<strong>Wh-word + Auxiliary + Subject + Verb<\/strong> — питальне слово на початку, потім допоміжне дієслово.",
            "examples": [
                {
                    "en": "Where do you live?",
                    "ua": "Де ти живеш?"
                },
                {
                    "en": "What did she eat?",
                    "ua": "Що вона їла?"
                },
                {
                    "en": "Why are they running?",
                    "ua": "Чому вони біжать?"
                },
                {
                    "en": "How can I help?",
                    "ua": "Як я можу допомогти?"
                }
            ]
        },
        {
            "label": "Wh-слово як підмет",
            "color": "amber",
            "description": "Якщо <strong>Who<\/strong> або <strong>What<\/strong> є підметом, допоміжне дієслово <strong>не потрібне<\/strong>.",
            "examples": [
                {
                    "en": "Who called you?",
                    "ua": "Хто тобі дзвонив?"
                },
                {
                    "en": "What happened?",
                    "ua": "Що сталося?"
                },
                {
                    "en": "Who lives here?",
                    "ua": "Хто тут живе?"
                }
            ],
            "note": "Порівняй: <strong>Who called you?<\/strong> (who — підмет) vs <strong>Who did you call?<\/strong> (you — підмет)."
        }
    ]
}

{
    "title": "4. Заперечення (Negatives)",
    "sections": [
        {
            "label": "Звичайні дієслова",
            "color": "emerald",
            "description": "Додай <strong>do\/does\/did + not<\/strong> перед основним дієсловом.",
            "examples": [
                {
                    "en": "I do not (don't) like apples.",
                    "ua": "Я не люблю яблука."
                },
                {
                    "en": "She does not (doesn't) play football.",
                    "ua": "Вона не грає у футбол."
                },
                {
                    "en": "They did not (didn't) see the movie.",
                    "ua": "Вони не бачили фільм."
                }
            ]
        },
        {
            "label": "To be та модальні дієслова",
            "color": "sky",
            "description": "Додай <strong>not<\/strong> безпосередньо після to be або модального дієслова.",
            "examples": [
                {
                    "en": "He is not (isn't) ready.",
                    "ua": "Він не готовий."
                },
                {
                    "en": "She was not (wasn't) there.",
                    "ua": "Її там не було."
                },
                {
                    "en": "You must not (mustn't) touch it.",
                    "ua": "Ти не повинен це чіпати."
                },
                {
                    "en": "They cannot (can't) come.",
                    "ua": "Вони не можуть прийти."
                }
            ]
        }
    ]
}

{
    "title": "5. Скорочені форми (Contractions)",
    "intro": "У розмовній мові not часто скорочується:",
    "rows": [
        {
            "en": "do not",
            "ua": "don't",
            "note": "I don't know."
        },
        {
            "en": "does not",
            "ua": "doesn't",
            "note": "She doesn't like it."
        },
        {
            "en": "did not",
            "ua": "didn't",
            "note": "We didn't go."
        },
        {
            "en": "is not",
            "ua": "isn't",
            "note": "He isn't here."
        },
        {
            "en": "are not",
            "ua": "aren't",
            "note": "They aren't coming."
        },
        {
            "en": "will not",
            "ua": "won't",
            "note": "I won't forget."
        },
        {
            "en": "cannot",
            "ua": "can't",
            "note": "She can't swim."
        }
    ],
    "warning": "📌 У формальному письмі використовуй повні форми."
}

{
    "title": "6. Типові помилки україномовних",
    "items": [
        {
            "label": "Помилка 1",
            "color": "rose",
            "title": "Відсутнє допоміжне дієслово у питанні.",
            "wrong": "You like pizza?",
            "right": "✅ <span class=\"font-mono\">Do you like pizza?<\/span>"
        },
        {
            "label": "Помилка 2",
            "color": "amber",
            "title": "Відсутнє допоміжне дієслово у Wh-питанні.",
            "wrong": "Where you live?",
            "right": "✅ <span class=\"font-mono\">Where do you live?<\/span>"
        },
        {
            "label": "Помилка 3",
            "color": "sky",
            "title": "Неправильний вибір do\/does.",
            "wrong": "She don't like it.",
            "right": "✅ <span class=\"font-mono\">She doesn't like it.<\/span>"
        },
        {
            "label": "Помилка 4",
            "color": "purple",
            "title": "Заперечення без допоміжного дієслова.",
            "wrong": "I no like apples.",
            "right": "✅ <span class=\"font-mono\">I don't like apples.<\/span>"
        }
    ]
}

{
    "title": "8. Практика",
    "select_title": "Вправа 1. Обери правильний варіант",
    "select_intro": "Обери речення з правильним порядком слів.",
    "selects": [
        {
            "label": "a) Do you like coffee? / b) You like coffee?",
            "prompt": "Який варіант правильний?",
            "answer": "a"
        },
        {
            "label": "a) Where does she live? / b) Where she lives?",
            "prompt": "Який варіант правильний?",
            "answer": "a"
        },
        {
            "label": "a) He don't work here. / b) He doesn't work here.",
            "prompt": "Який варіант правильний?",
            "answer": "b"
        }
    ],
    "options": [
        "a",
        "b"
    ],
    "input_title": "Вправа 2. Побудуй питання",
    "input_intro": "Перетвори ствердження на питання.",
    "inputs": [
        {
            "before": "You speak English.",
            "after": "→ Do you...?",
            "answer": "Do you speak English?"
        },
        {
            "before": "She works in a bank.",
            "after": "→ Does she...?",
            "answer": "Does she work in a bank?"
        },
        {
            "before": "They went to the party.",
            "after": "→ Did they...?",
            "answer": "Did they go to the party?"
        }
    ],
    "rephrase_title": "Вправа 3. Побудуй заперечення",
    "rephrase_intro": "Перетвори ствердження на заперечення.",
    "rephrase": [
        {
            "example_label": "Приклад:",
            "example_original": "I like apples.",
            "example_target": "I don't like apples."
        },
        {
            "original": "1. She plays tennis.",
            "placeholder": "Напиши заперечення",
            "answer": "She doesn't play tennis."
        },
        {
            "original": "2. They watched the movie.",
            "placeholder": "Напиши заперечення",
            "answer": "They didn't watch the movie."
